  for(var at:coal.subList(3,67)){p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));BlacksmithRepairRuntime.near(p,at);h.assertTrue(p.gameMode.destroyBlock(at),"Actual native correct-tool coal extraction succeeds");}
  for(var at:iron.subList(0,48)){p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));BlacksmithRepairRuntime.near(p,at);h.assertTrue(p.gameMode.destroyBlock(at),"Actual native correct-tool iron extraction succeeds");}
  h.assertTrue(data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"coal")==64&&data.evidence().count(p.getUUID(),ProfessionRank.APPRENTICE,"iron")==48,"Exactly112actual native removals, no count injection");CreateCraftRuntime.counter(p,project);for(String quest:NativeOreQuests.GOALS.keySet()){var q=ProfessionService.review(p,"quest:"+quest);ProfessionService.confirm(p,q.nonce());boolean refused=false;try{ProfessionService.review(p,"quest:"+quest);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Completed natural extraction cannot award twice");}h.assertTrue(store.professions(p.getUUID()).track(Profession.MINER).xp()==400,"Actual coal/iron plus retained masonry earn400XP; missing prerequisites still prevent rank");CommerceService.verifyReceipt(p);h.assertTrue(EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data")).professions(p.getUUID()).equals(store.professions(p.getUUID())),"Canonical mining operations reopen with original roster");var proof=new CompoundTag();proof.putLong("retained",coal.get(67).asLong());proof.putLong("spent",coal.get(3).asLong());AtomicNbt.write(proofPath,proof);com.mojang.logging.LogUtils.getLogger().info("NATIVE_ORE_NATIVE_PASSED: real asynchronous decorated Overworld OreFeature ProtoChunk generation/promotion, native replacement/barehand/current FTB+OPAC refusal/corrupt evidence transaction safety,112real correct-tool removals/64coal48iron and original counter canonical400XP/replay refusal; private future terrain/raw tools/native mining time only, no ore or evidence/XP injection");
